package com.noahprail.kairos.protocol

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonNull
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.boolean
import kotlinx.serialization.json.jsonArray
import kotlinx.serialization.json.jsonObject
import kotlinx.serialization.json.jsonPrimitive
import kotlinx.serialization.json.long
import java.io.File

/** Loads protocol/test-vectors.json (generated by the Node reference implementation) as plain JSON. */
class Vectors(val root: JsonObject) {
    fun list(key: String): List<JsonObject> = root[key]!!.jsonArray.map { it.jsonObject }
    val auth: JsonObject get() = root["auth"]!!.jsonObject

    companion object {
        fun load(): Vectors {
            // Gradle runs unit tests from apps/android/app; the vectors live at <repo>/protocol.
            var dir: File? = File("").absoluteFile
            while (dir != null && !File(dir, "protocol/test-vectors.json").exists()) dir = dir.parentFile
            val file = File(requireNotNull(dir) { "protocol/test-vectors.json not found" }, "protocol/test-vectors.json")
            return Vectors(Json.parseToJsonElement(file.readText()).jsonObject)
        }
    }
}

fun JsonObject.str(key: String): String = this[key]!!.jsonPrimitive.content
fun JsonObject.long(key: String): Long = this[key]!!.jsonPrimitive.long
fun JsonObject.int(key: String): Int = long(key).toInt()
fun JsonObject.bool(key: String): Boolean = this[key]!!.jsonPrimitive.boolean
fun JsonObject.obj(key: String): JsonObject = this[key]!!.jsonObject
fun JsonObject.arr(key: String): JsonArray = this[key]!!.jsonArray
fun JsonObject.optInt(key: String): Int? = this[key]?.takeIf { it !is JsonNull }?.jsonPrimitive?.long?.toInt()
fun JsonObject.optStr(key: String): String? = this[key]?.takeIf { it !is JsonNull }?.jsonPrimitive?.content
fun JsonObject.hex(key: String): ByteArray = hexBytes(str(key))

fun ByteArray.hex(): String = joinToString("") { "%02x".format(it) }

fun hexBytes(hex: String): ByteArray = ByteArray(hex.length / 2) { hex.substring(it * 2, it * 2 + 2).toInt(16).toByte() }

/** The wire config of a vector, as the app's model. */
fun configFrom(j: JsonObject): CameraConfig = CameraConfig(
    name = j.str("name").ifEmpty { null },
    cameraType = j.str("cameraType"),
    wakeUpTimeout = j.int("wakeUpTimeout").toDouble(),
    startBefore = j.int("startBefore").toDouble(),
    endAfter = j.int("endAfter").toDouble(),
    zcam = CameraConfig.Zcam(j.optStr("cameraIp")),
    attempts = j.arr("attempts").map { CameraConfig.Attempt(it.jsonObject.str("name"), it.jsonObject.long("time")) },
)
